quests[51544] = { id = 51544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonen ausschalten", description = "Mit Euch ist vielleicht auch unsere Rettung gekommen. Mit Euren Ruderbooten können wir die am schwersten Verletzten evakuieren.\n\nLeider hat die Horde ein Schiff in Position gebracht. Wir kommen niemals mit den Booten an ihrer Blockade vorbei.\n\nWährend der Rest von uns die Verwundeten in die Boote bringt, müsst Ihr das Schiff infiltrieren und die Kanonen unbrauchbar machen.", sourceObjective = "Macht die Kanonen auf dem Hordenschiff unbrauchbar.", completion = "Jetzt können wir unsere Verwundeten in Sicherheit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51545] = { id = 51545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böser Brecher", description = "Die geballte Feuerkraft aller Bomben, die Ihr gesammelt habt, sollte den Riffbrecher der Venture Co. zerstören können.\n\nEs wird Zeit, zu handeln und das Riff sowie diese heilige Höhle zu schützen.", sourceObjective = "Zerstört den Riffbrecher.", completion = "Ihr habt uns einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51546] = { id = 51546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drecksgrube" }
quests[51547] = { id = 51547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Wassergram", description = "Eine grässliche Monstrosität aus Fleisch und Holz terrorisiert die Gegend um den Fluss in der Nähe.\n\nWenn es einem kühnen Abenteurer gelingen sollte, die Bestie zu bezwingen, würde sich Fallhafen sicherlich erkenntlich zeigen.\n\nMeldet Euch bei Bürgermeister Weiß, wenn Ihr helfen wollt.", sourceObjective = "Besiegt Wassergram außerhalb von Fallhafen.", completion = "Die Bestie ist tot? Ich danke Euch vielmals, {class}.\n\nHier ist die versprochene Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[51548] = { id = 51548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagative Gedanken" }
quests[51550] = { id = 51550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Toten und Blasen" }
quests[51552] = { id = 51552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So viel zu tun", description = "Guten Tag! Könnt Ihr mir vielleicht bei einer Sache helfen?\n\nUnteroffizier Calvin sollte mich eigentlich hier treffen. Wir wollten losziehen und nach neuen alchemistischen Reagenzien suchen, aber er ist immer noch nicht hier.\n\nIch weiß, dass die Miliz in letzter Zeit sehr viel zu tun hatte, also ist er wahrscheinlich beschäftigt, aber er sollte sich immer noch am Brennadamplatz aufhalten. Könnt Ihr bitte für mich nach ihm sehen?", sourceObjective = "Findet Unteroffizier Calvin am Brennadamplatz.", completion = "Das darf doch nicht wahr sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[51554] = { id = 51554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachladen", description = "Derek landet fast nur Volltreffer, aber die Horde ist zahlenmäßig hoffnungslos überlegen. Wir brauchen schleunigst mehr Munition!\n\nNehmt diese Notiz und bringt sie Onkel Leo in der Totenschwemme. Er wird uns helfen können.", sourceObjective = "Bringt die Notiz zu Leo Schilders.", completion = "Leefke Martinek? Die ist ganz schön zäh! Ich werde versuchen, ihr zu helfen, aber wir müssen erst unsere Leute retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51555] = { id = 51555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Kurs halten", description = "Prinzessin Talanjis Aktionen haben unsere Verfolger aufgehalten. Ihr Loa ist wahrlich sehr mächtig.\n\nWir müssen sichergehen, dass mögliche Überlebende in Zandalar keinen Stützpunkt errichten können. Ich befürchte, dass unsere Landsleute bei den Verlassenen etwas... übereifrig werden könnten. Bitte behaltet sie im Auge und erinnert sie daran, was Ehre bedeutet.", sourceObjective = "Sprecht mit Dennis Düstermär in Talanjis Tadel.", completion = "Hat man Euch geschickt, um nach mir zu sehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[51557] = { id = 51557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung der Eisenfluträuber", description = "Die Horde überrennt diese Stadt! Ich werde sicher nicht hierbleiben und mir das ansehen!\n\nIhr könntet mir aber helfen. Sucht Leo Schilders in der Totenschwemme auf.\n\nBerichtet ihm, dass die Eisenfluträuber noch immer auf dem Weg sind und dass wir uns das Gold holen!", sourceObjective = "Sprecht mit Leo Schilders in der Totenschwemme.", sourceObjectiveStatus = "unverified-source-field" }
quests[51558] = { id = 51558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnen schmoren" }
