quests[51565] = { id = 51565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fressattacke" }
quests[51566] = { id = 51566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederkehr der Bestie" }
quests[51568] = { id = 51568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituelle Vorbereitungen", description = "Hey! Ich habe eine Anfrage nach einer Ladung Sturmsilber. Habt Ihr Lust, zu helfen?\n\nWie Ihr wisst, ist Sturmsilber sehr leicht und korrosionsbeständig. Ihr wisst aber vielleicht nicht, dass wir es überall in unseren Schiffen verwenden. Es ist so leicht, dass unsere Seeleute und Piraten es zur Herstellung von Rüstung benutzen, weil sie darin schwimmen können!\n\nAllerdings müssen alle Teile, die auf einem Schiff verwendet werden, von einem Gezeitenweisen gesegnet werden, oder das Schiff ist einem wässrigen Untergang geweiht!\n\nSammelt einen Eimer voll Erz, verhüttet es und lasst es für mich segnen. Dann bringe ich Euch bei, wie Ihr es leichter abbauen könnt.", sourceObjective = "Baut ungeweihtes Sturmsilbererz ab, verhüttet es in einer Schmiede zu ungeweihten Sturmsilberbarren und lasst diese von einem Gezeitenweisen segnen.", completion = "Gute Arbeit! Die sehen großartig aus!\n\nDiese Barren werden in unserem nächsten Kriegsschiff verarbeitet werden.\n\nNun denn, eine Hand wäscht die andere und ich werde Eure waschen. Sturmsilber ist von Natur aus sehr brüchig. Wenn Ihr es abbaut, schlagt lieber mehrmals vorsichtig zu, als einmal richtig hart. Dann wird das Metall nicht splittern.", sourceObjectiveStatus = "unverified-source-field" }
quests[51569] = { id = 51569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zandalarkampagne", description = "Wir müssen jetzt anfangen, an unsere Feinde zu denken, {name}. Die Horde weitet ihren Einfluss in Zandalar ohne Gegenwehr aus.\n\nKönig Anduin hat uns damit beauftragt, Stützpunkte in den Regionen Zuldazar, Nazmir und Vol'dun zu errichten.\n\nIch habe mir die Freiheit genommen, einige unserer Streitkräfte an Schlüsselpositionen aufzustellen, aber sie brauchen einen fähigen Kommandanten. Ihr seid genau <der/die> Richtige, um unsere Bestrebungen dort umzusetzen.\n\nWelche Region wollt Ihr als Erstes sichern?", sourceObjective = "Verwendet die Kampagnenkarte von Zandalar, um einen Stützpunkt auszuwählen.", completion = "Eine gute Wahl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51570] = { id = 51570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Zuldazar", description = "Zuldazar ist das Machtzentrum des Zandalariimperiums.\n\nIch habe einige meiner Maulwurfmaschinen an einem Ort namens Xibala eingesetzt. In der Nähe gibt es ein Azeritvorkommen, das den König sehr interessieren wird. Meine Jungs sagen, sie werden angegriffen.\n\n                 - Moira Thaurissan", sourceObjective = "Helft Kelsey Stahlfunken in Zuldazar.", sourceObjectiveStatus = "unverified-source-field" }
quests[51571] = { id = 51571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Nazmir", description = "Der Sumpf von Nazmir ist die Heimat der berüchtigten Bluttrolle.\n\nHauptmann Conrad wurde dort hingeschickt, um einzuschätzen, wie wir ihren Hass auf die Zandalari für unsere Zwecke nutzen können. Berichte aus dem Dschungel lassen nichts Gutes erahnen.\n\n                     - Mathias Shaw", sourceObjective = "Helft Brann Bronzebart in Nazmir.", sourceObjectiveStatus = "unverified-source-field" }
quests[51572] = { id = 51572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Vol'dun", description = "In der Wüste von Vol'dun gibt es einen Hafen, der vielversprechend für unsere Flotte aussieht.\n\nDas Gebiet wird von einem einheimischen Schlangenvolk besetzt, das man als die Sethrak kennt. Sie sind aggressiv und lassen nicht mit sich verhandeln. Uns bleibt kaum eine andere Wahl, als sie auszuschalten.\n\n                    - Magister Umbric", sourceObjective = "Helft den Allianzstreitkräften in Vol'dun.", sourceObjectiveStatus = "unverified-source-field" }
quests[51573] = { id = 51573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Es is' schön, hier mal 'n neues Gesicht zu seh'n. Ich hab da ein Problem und Ihr seht aus, als ob Ihr kampferfahr'n seid.\n\nDiese mörderisch'n Schurken dort sin' auf Krawall aus und ich bin ihnen alleine nich' gewachs'n.\n\nIch war mal auch einer von denen, aber ich bin ausgestieg'n, um's mit 'nem rechtschaffenen Leben zu versuch'n.\n\nIch muss Mojambo und seine Bande überzeug'n zu geh'n, bevor sie hier den andren Ausgestoßenen Ärger mach'n.", sourceObjective = "Beschützt Razgaji, während er sich mit Mojambo trifft.", progress = "Mojambo wird sich nich' einfach so zurückzieh'n.", completion = "Mojambo wird mit seinen ganzen Leuten zurückkomm'n, und wenn das passiert, wird Blut fließ'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51574] = { id = 51574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch gepresst", description = "Ist das eine Trollfreundin von Euch? Ich bin so froh, dass Kiro mir erlaubt hat, mich um sie zu kümmern.\n\nEr ist Fremden gegenüber zwar skeptisch eingestellt, aber er ist ein guter Heiler.\n\nIch verspreche Euch, dass sie aufwachen wird. Und wenn das passiert, wird sie sehr durstig sein.\n\nHier in der Wüste gibt es kaum Wasser, aber Ihr habt Glück. Der Hain, der dieses Lager umgibt, ist von Stacheldickblättern nur so überwuchert.\n\nDas Fruchtfleisch kann man nicht essen, aber der enthaltene Saft ist der beste Durstlöscher weit und breit.\n\nDrückt sie einfach kräftig aus und fangt den Saft auf.", sourceObjective = "Presst 8-mal Stacheldickblattsaft aus.", progress = "Habt Ihr den Saft? Eure Freundin wird durstig sein, wenn sie erwacht.", completion = "Das ist eine Menge Saft!", sourceObjectiveStatus = "unverified-source-field" }
quests[51575] = { id = 51575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren, aber nicht vergessen", description = "He da, {name}, habt Ihr Interesse, 'nen persönlichen Gegenstand zurückzuhol'n?\n\nIn Xibala is 'n Raptor, und der hat 'n uraltes und wertvolles Artefakt von meinem Volk geklaut. Ich hab versucht, mit dem Vieh zu red'n, aber das lief nich' so gut und endete mit gegenseitigem Anschrei'n und Beiß'n.\n\nFindet den Raptor Knochenkreischer un' tötet ihn. Dann bringt mir das verlor'ne Artefakt.\n\nAls Gegenleistung zeig ich Euch, wie man diese Viecher besser häutet.", sourceObjective = "Tötet Knochenkreischer und bringt das \"uralte Artefakt\" zu Rana der Schlitzerin.", progress = "Habt Ihr das Biest schon umgebracht?\n\n<Rana kichert und grinst verschlagen.>", completion = "Aha! Sieh ma' einer an! Ich dacht, ich würd dich nich' wiederseh'n!\n\n<Rana knuddelt den kleinen ausgestopften Raptor glücklich.>\n\nWas soll'n das Gesicht? Ich hab die Wahrheit gesagt.\n\nIch hab ihn als Kind verlor'n, das is' fast 'n ganzes Leben her. Er hat groß'n sentimentalen Wert für mich, un' ich gehör zu meinem Volk.\n\nAber Ihr habt das getan, worum ich Euch gebet'n hab, also bring ich Euch was bei.\n\n<Rana erklärt fröhlich ein paar unbekanntere Methoden, um Leder zu gewinnen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51576] = { id = 51576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine tote Hexe ist eine gute Hexe" }
