quests[51581] = { id = 51581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritbergbau" }
quests[51582] = { id = 51582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie das Land, so der Mildenhall", description = "Ihr habt sicherlich schon ein oder drei Krüge des weltberühmten Mildenhallmets in Eurer Stammtaverne zu Euch genommen. Heute ist der Tag, an dem Ihr zu einem Teil der offiziellen Metbrauerei des Sturmsangtals werdet!\n\nIdeale Bewerber sind verrückt nach hochwertigem Met, Honig und grenzenlosen Innovationen. Militärische Erfahrung ist ein Plus, aber keine Voraussetzung.\n\nIhr dürft nicht gegen Bienen allergisch sein.\n\nMildenhallmet - Wie das Land, so der Mildenhall.", sourceObjective = "Sprecht mit Anselm Mildenhall in der Metbrauerei Mildenhall.", completion = "<Anselm ist fast schon hysterisch.>", sourceObjectiveStatus = "unverified-source-field" }
