quests[51586] = { id = 51586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritermächtigung" }
quests[51587] = { id = 51587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts!", description = "Ich bin froh, dass Ihr gekommen seid, {name}. Mit Eurer Hilfe werden wir diesen Hunden aus Kul Tiras zeigen, was passiert, wenn man ein wildes Tier in die Ecke drängt!\n\nDie Reißzahnfeste liegt gleich den Pfad hier hoch. Kommt und ich erzähle Euch die weiteren Details.", sourceObjective = "Begleitet Rexxar.", completion = "Ich dachte schon, ich würde der Erdenmutter zusammen mit dem Rest meiner Männer gegenübertreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51588] = { id = 51588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertraute Feinde" }
quests[51589] = { id = 51589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen der Moral von Kul Tiras", description = "Unsere Partnerschaft mit den Zandalari dürfte bald gesichert sein. Es hat zwar etwas länger gedauert, als erwartet, aber bei solchen Angelegenheiten ist das eben manchmal so.\n\nLeider scheint die Allianz fest entschlossen zu sein, sich ihre eigene Seestreitkraft zu sichern, und das dürfen wir nicht zulassen.\n\nWenn Ihr so weit seid, hissen wir sofort die Segel und nehmen Kurs auf den Tiragardesund.", sourceObjective = "Segelt zum Tiragardesund.", completion = "Wir sind da. Jetzt gilt es, den Einheimischen etwas Ärger zu bereiten.\n\n<Nathanos schaut zuerst Euch und dann den Rest der Gruppe an.>\n\nWir machen doch keinen allzu verdächtigen Eindruck, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[51590] = { id = 51590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Herz von Tiragarde", description = "Der erste Schritt besteht darin, eine geeignetere Einsatzbasis zu errichten. Zur Not tut es auch eine Piratenhöhle, aber ich glaube, der Kriegshäuptling erwartet etwas Besseres von uns.\n\nTeilen wir uns auf und stoßen wir tiefer ins Landesinnere vor, und zwar Richtung Westen. Haltet die Augen nach etwas Unauffälligem auf, das sich gut verteidigen lässt.", sourceObjective = "Trefft Euch mit Nathanos und Lilian im Zentrum des Tiragardesunds.", completion = "<Nathanos wirft einen Blick um die Ecke auf das Lager der Raubeine von Kul Tiras.>\n\nDas wird ausreichen. Hier sind wir erstens gut im Wald versteckt, und zweitens scheinen die Einheimischen nicht sonderlich helle zu sein und sollten sich leicht überlisten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51591] = { id = 51591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Berg", description = "{name}, kümmert Euch um diese \"Raubeine\". Sie mögen sich ja für harte Kerle halten, aber eine Kostprobe Eurer unverkennbaren Hordenbrutalität dürfte sie ganz schnell in die Flucht jagen.\n\nLilian, Ihr kundschaftet die Gegend aus. Wir müssen wissen, ob es in der Nähe irgendwelche Bedrohungen gibt.\n\nWaldläufer, sichert das Gelände. Wir treffen uns dann im Lager der Raubeine wieder, wenn {name} mit <seiner/ihrer> Arbeit fertig ist.", sourceObjective = "Tötet 10 Raubeine im Baumfallaußenposten.", completion = "<Nathanos sieht sich im Lager um und nickt zustimmend.>\n\nDas wird ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51592] = { id = 51592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemütlich einrichten", description = "Blockhütten müssen zur Not reichen, aber... wenn wir hier einige Zeit verbringen wollen, können wir es uns auch bequem machen.\n\nDie Raufbolde haben uns reichlich Holz und Nahrung hinterlassen, aber wir brauchen Segeltuch und Ketten, um vernünftige Zelte und Banner der Verlassenen aufzustellen. Bronhavn macht einen recht plünderungswürdigen Eindruck, nicht wahr?", sourceObjective = "Besorgt 7 Kettenstücke und 7 Ballen Segeltuch aus den Außenbezirken von Bronhavn.", progress = "Hat \"Bro\" nicht etwas mit \"Brücke\" zu tun? Bei einem Namen wie Bronhavn gehe ich davon aus, dass die Stadt ein Umschlagplatz für viele Vorräte ist, die nur darauf warten, geplündert zu werden.", completion = "Ich werde dafür sorgen, dass die Waldläufer sofort mit ihrer Arbeit beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51593] = { id = 51593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung von Bronhavn", description = "Wenn Ihr schon in Bronhavn seid, könntet Ihr Euch auch ein wenig nach Informationen umhören, die für uns nützlich sein könnten.\n\nIhr wärt überrascht, was man alles erfahren kann, wenn man schweigt und nur den Leuten zuhört, die denken, dass sie alleine sind...", sourceObjective = "Spioniert die Bewohner von Bronhavn aus.", completion = "Sprengstoff in der Aschenwindgießerei? Diese Information können wir mit Sicherheit verwenden. Gut gemacht.\n\nEs klingt so, als ob diese Kapitänin Stein auch eine große Nummer ist. Es wäre doch schade, wenn ihr etwas zustoßen würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[51594] = { id = 51594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengstoff in der Gießerei", description = "Aber am meisten interessiert mich dieser Sprengstoff.\n\nTrefft Euch mit mir in der Gießerei östlich von hier. Ihr seid wahrscheinlich auf Eurem Weg von Raubhafen hindurchgekommen.", sourceObjective = "Trefft Euch mit Lilian Voss an der Aschenwindgießerei.", completion = "<Lilian zeigt auf einen Stapel Kisten in der Nähe.>\n\nMeint Ihr, die sind voller Sprengstoff?", sourceObjectiveStatus = "unverified-source-field" }
quests[51595] = { id = 51595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochexplosiv", description = "Ich will Eure Zeit nicht verschwenden. Wir sollten ganz sichergehen, dass sie das sind, wonach wir suchen.\n\nHier, nehmt diese Fackel und werft sie hinüber zu den Kisten. Wenn sie explodieren, wissen wir, was als Nächstes zu tun ist.", sourceObjective = "Benutzt Lilians Fackel bei dem Stapel Aschenwindkisten in der Nähe der Aschenwindgießerei.", completion = "Ich... äh... ich schätze, wir haben unser Schießpulver wohl gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51596] = { id = 51596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Munitionsbeschaffung", description = "Als Erstes holen wir so viel Schießpulver wie nur möglich. Stellt Euch das Entsetzen in den Augen der Kul Tiraner vor, wenn sie erkennen, dass die Horde ihre eigenen Waffen gegen sie verwendet.\n\nStellt es Euch vor, {name}.\n\n<Lilians Augen werden kurz glasig und ihre Mundwinkel verziehen sich zu einem schwachen Lächeln.>", sourceObjective = "Besorgt 8 Kisten mit Aschenwindsprengstoff.", progress = "Ich habe es geschafft, selbst ein paar Kisten zusammenzutragen. Wie ist es bei Euch gelaufen?", completion = "Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[51597] = { id = 51597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießpulverforschung", description = "Ich schätze, bevor wir das hochexplosive Schießpulver der Kul Tiraner stehlen, um es gegen sie zu verwenden, sollten wir lernen, wie sie das Zeug herstellen.", sourceObjective = "Besorgt die Formel für den Aschenwindsprengstoff und die Anleitung zur Schießpulverherstellung.", progress = "Lasst mal die Papiere sehen.", completion = "<Lilian überfliegt die Dokumente und nickt.>\n\nIch nehme an, dass jemand in der Horde diese Informationen nützlich finden wird.\n\nWahrscheinlich Goblins.", sourceObjectiveStatus = "unverified-source-field" }
quests[51598] = { id = 51598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für eine Handvoll Chaos", description = "Für eine Produktionsanlage ist sie ganz schön gut verteidigt, oder?\n\n<Lilian zuckt mit den Schultern.>\n\nIch schätze, wir werden sie wohl töten müssen.", sourceObjective = "Tötet 15 Arbeiter in der Aschenwindgießerei.", completion = "<Lilian lässt die Klinge in ihren Händen hüpfen, sieht hoch und nickt Euch anerkennend zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51599] = { id = 51599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesfalle", description = "Wir haben diese Mission mit einem Ziel, aber mit nur wenig Planung begonnen. Ich glaube aber, ich sehe, wie sich alles zusammenfügt.\n\n<Lilian betrachtet nachdenklich den Horizont.>\n\nPlatziert diese Sprengladungen drüben am Südwestrand der Stadt. Irgendwo, wo sie nicht auffallen.\n\nWir treffen uns dann da drüben wieder. In der Zwischenzeit... muss ich ein Pferd finden.", sourceObjective = "Stellt 8 Schießpulverkisten an einem versteckten Ort südwestlich von Bronhavn auf.", completion = "Zum Glück für uns gibt es hier genug Pferde.\n\nHabt Ihr das Schießpulver platziert?", sourceObjectiveStatus = "unverified-source-field" }
quests[51601] = { id = 51601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bronhavnfahrt", description = "Passt gut auf, {name}, denn das hier wird keine Nullachtfünfzehn-Attentatsmission.\n\nWir beide werden mit diesem Pferd durch Bronhavn reiten und... für einen Tumult sorgen. Ich will, dass jede einzelne Wache einschließlich dieser Kapitänin Stein uns verfolgt. Sobald wir sie alle zusammen haben, geht's hinüber zu den Sprengladungen und...\n\n<Lilians Augen weiten sich vor Entzücken.>\n\nBumm.", sourceObjective = "Steigt auf das gestohlene Pferd und benutzt es dann, um 10 Wachen von Bronhavn und Kapitänin Stein zusammenzurufen. Dann führt sie zur südwestlichen Ecke der Stadt.\n\nWenn Ihr vom Pferd gestoßen werdet, könnte das tödlich enden, und die Mission wird scheitern.", completion = "Ich habe die Explosion bis hierhin gehört. Ich glaube, ich habe sogar ein Stückchen Wache auf meinem Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[51602] = { id = 51602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banditenklingen", description = "Wir könn' mit unsren Waffen nur die Hälfte des Stamms geg'n Mojambos Bande bewaffnen.\n\nWir werd'n mehr Waffen brauch'n, wenn wir die kommende Schlacht überleb'n woll'n.\n\nTongos Leute ham bestimmt 'ne Menge Waffen in ihrem Versteck.\n\nDurchsucht das Versteck nach Waffen un' bringt sie zurück zur Arena.", sourceObjective = "Sammelt 8 sandgeschliffene Klingen.", progress = "Habt Ihr die Waff'n?", completion = "Die uralten Klingen sin' zwar nich' in der besten Verfassung, aber sie sin' meisterlich gefertigt. Sie werd'n uns in der Schlacht gute Dienste erweis'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51604] = { id = 51604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gejagte Jäger" }
