quests[51643] = { id = 51643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eiserner Wall", description = "Der Feind hat unsere Männer an die Küste zurückgedrängt und ihre Schiffe versenkt. Sie haben keine Rückzugsmöglichkeit. Wir müssen sie retten!\n\nGeht unter Deck, bemannt eine Kanone und gebt ihnen Feuerschutz. Ohne uns sind sie verloren!", sourceObjective = "Bemannt eine Kanone und tötet 40 Soldaten aus Kul Tiras.", completion = "Gute Arbeit. Jetzt haben unsere Truppen wieder ein bisschen Luft zum Atmen.", sourceObjectiveStatus = "unverified-source-field" }
