quests[51662] = { id = 51662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsschrecken der Fuchsbauwaldung" }
quests[51663] = { id = 51663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf den Untergang", description = "<Überall auf dem Tempelgelände finden sich große Mengen an Vorräten. Viele davon werden schwer bewacht. Die Jambani bereiten sich anscheinend auf eine Belagerung oder ein anderes bedeutendes Ereignis vor.\n\nZul würde es sicher als weise erachten, ihr Vorhaben zu sabotieren.>", sourceObjective = "Zerstört 8 Vorräte der Jambani.", completion = "Gut. Ich musste Euch nich' sagen, dass Ihr das tun sollt.\n\nDie Jambani bereit'n sich auf den Untergang von Zuldazar vor, so wie es von Vol'jamba vorausgesagt word'n is'. Das wird nich' passier'n. Aber wenn wir ihre Vorräte zerstör'n, sind sie ein leichteres Ziel, wenn sich Rastakhan später dazu entscheidet, sich um sie zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[51664] = { id = 51664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kulett die Störrische" }
quests[51665] = { id = 51665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutmutter Razora" }
quests[51666] = { id = 51666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baschmu" }
quests[51667] = { id = 51667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vogel muss frei sein" }
quests[51668] = { id = 51668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojambo", description = "Mojambo und seine Bande greif'n an!\n\nWir müss'n die Arena verteidig'n. Mojambo muss sterb'n! Die Ausgestoß'nen kümmern sich um seine Bande. Mojambo gehört ganz Euch...\n\nNehmt Tongos Kopf mit und verwendet ihn, um Mojambo zu 'nem Duell herauszufordern. Er is' so übertrieben stolz, dass er diese Herausforderung nich' ablehn' wird!", sourceObjective = "Tötet Mojambo.", progress = "Mojambo muss sterb'n!", completion = "Immerhin is' dieser Krieg jetz' vorbei un' wir könn' in Frieden leb'n. Ich weiß nich', wie ich Euch für all das dank'n soll, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51669] = { id = 51669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarzäugige Bartholomäus" }
quests[51670] = { id = 51670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifholzwächter" }
quests[51671] = { id = 51671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegenbockbarbier", sourceObjective = "Verwendet die Ziegenschere bei 6 sanftmütigen Ziegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51672] = { id = 51672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verworrene Netze" }
quests[51674] = { id = 51674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen löschen", description = "Riecht Ihr das, {name}? Rauch! Sie brennen die Reißzahnfeste nieder!\n\nUnsere Schlacht hat nicht viel Sinn, wenn unsere Basis dem Erdboden gleichgemacht wird!\n\nIhre Gezeitenweisen benutzen Zauberstäbe, um ihre Wasserkonstrukte zu kontrollieren. Wenn wir diese in die Hände bekämen, hätten wir vielleicht eine Chance, die Feste zu retten!\n\nHolt diese Zauberstäbe und löscht die Brände, bevor das Lager zu Schutt und Asche verbrannt wird!", sourceObjective = "Besorgt einen schwindenden Umbralzauberstab und benutzt ihn, um 4 Brände in der Reißzahnfeste zu löschen.", progress = "Wir haben großes Glück, dass die Kul Tiraner eine größere Vorliebe für Wasser als für Feuer haben.", completion = "Feuer, Blut, Krieg. Nichts kann uns aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51675] = { id = 51675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie zur Strecke", description = "Diese Leute aus Kul Tiras scheinen nicht normal zu sein. Menschen können, nach allem, was ich höre, ganz schön grausam sein, aber diese scheinen besondere Freude daran zu haben, die Gefallenen abzuschlachten.\n\nDie Schlimmste unter ihnen war eine Frau mit einer merkwürdigen Maske. Sie schien den anderen Befehle zuzurufen, also schätze ich, dass sie ihre Anführerin ist.\n\nEhrt die Gefallenen und sorgt dafür, dass die Kul Tiraner und ihre Anführerin nicht überleben.", sourceObjective = "Tötet Hauptmann Ara und 8 Fußsoldaten der Sturmwacht.", completion = "Ihr habt uns einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51676] = { id = 51676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weil ich ein Möwchen bin" }
quests[51677] = { id = 51677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Geist heilen", description = "Gut. Ihr habt mir die letzten Zutaten gebracht, die ich brauche, um eine Tinktur für die Wunden des Königs zusammenzubrauen.\n\nIhr seid keinen Moment zu früh. Er wird immer schwächer.\n\nIch arbeite nicht gerne schneller als sonst, aber die Situation erfordert es. Ihr müsst als meine Hände fungieren, denn ich bin sehr langsam.\n\nBringt mir, was ich brauche, und überlasst die Sorge um den Rest Jamil und mir.\n\nSprecht mich an, wenn Ihr bereit seid, zu beginnen.", sourceObjective = "Folgt Jols Anweisungen, um bei der Heilung von König Rastakhan zu helfen.", completion = "<Jol keucht.>\n\nDas hat... nicht ganz so funktioniert, wie ich mir das gedacht hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[51678] = { id = 51678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rastakhans Macht", description = "Seht Ihr das Schiff in der Bucht, {name}?\n\nDas is' mein Flaggschiff, die Rastakhans Macht. Es is' nicht auf meinen Befehl hier.\n\nUm den Propheten Zul werd'n wir uns später kümmern. Erst mal müssen die büß'n, die sich mein Schiff genommen ham.\n\nBringt mir den Kopf von Windrufer Ula'jan. Ohne ihn bewegt sich das Schiff keinen Meter. Und wenn er tot is', wird es das erst recht nicht.", sourceObjective = "Holt Windrufer Ula'jans Schädel von Bord des Flaggschiffs Rastakhans Macht.", progress = "Ohne den Windrufer kann mein Schiff nicht dazu verwendet werd'n, meine Herrschaft herauszufordern.", completion = "Den werd ich als Mahnmal hinter meinem Thron ausstell'n. Wer Rastakhan hintergeht, kann sich von seinem Leben verabschied'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51679] = { id = 51679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiger Anlaufhafen", description = "Ich weiß, dass Rastakhan wütend is', weil sie von allen Schiff'n unsrer Marine ausgerechnet sein Schiff an sich gebracht ham.\n\nDoch da gibt's noch 'ne interessant're Frage. Warum ham sie's hergebracht?\n\nZeb'ahari is'n kleines Fischerdorf. Hier gibt's keine Krieger, keine mächtig'n Anhänger des Königs. Es muss 'nen andren Grund geb'n.\n\nGeht an Bord des Schiffs und seht Euch gründlich um. Versucht herauszufind'n, warum die dieses Monstrum von 'nem Schiff hier rausgebracht ham.", sourceObjective = "Durchsucht die Rastakhans Macht nach Hinweisen.", completion = "Ich glaub, ich weiß, was das zu bedeut'n hat, {name}, und das is' nichts Gutes für meinen Loa.", sourceObjectiveStatus = "unverified-source-field" }
quests[51680] = { id = 51680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bwonsamdis Schatten", description = "Hier stimmt was nich', {name}.\n\nMein König wurd von den Loas gesegnet, wie Ihr's Euch nich' vorstell'n könnt. Ihm wurd 'n langes Leb'n, schnelle Heilung und mehr Stärke verlieh'n, als die meist'n Trolle besitz'n. Trotzdem steht er immer noch an der Schwelle zum Tod. Ich kann Bwonsamdi geradezu lach'n hör'n.\n\nZwei seiner zuverlässigsten Heiler sind bei ihm. Geht und findet raus, was da so lange dauert.\n\nIch werd dafür sorg'n, dass die nich' gestört werd'n.", sourceObjective = "Sprecht mit Jol dem Uralten und Jamil Abul'housin.", progress = "Seid Ihr gekommen, um dem König zu helfen?", completion = "Jetzt versteht Ihr, wie heikel diese Situation ist. Wir werden Eure Hände brauchen, wenn wir den komplizierten Heilungsprozess, der vor uns liegt, erfolgreich abschließen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51681] = { id = 51681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Hexe" }
