quests[51690] = { id = 51690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatten von Korlach" }
quests[51691] = { id = 51691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinahe rettungswürdig", description = "Wir haben versucht, so viele unserer Leute wie möglich aus der Festung zu evakuieren, doch einige der Peons hatten nicht so viel Glück.\n\nAls Kämpfer sind sie nicht zu gebrauchen, aber wir werden ihre Arbeitskraft in Zukunft noch benötigen.\n\nBitte, rettet sie, wenn Ihr könnt.", sourceObjective = "Rettet 6 verängstigte Peons aus der Reißzahnfeste.", completion = "Gute Arbeit, {name}. Wir werden ihre Arbeitskraft beim Wiederaufbau brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51693] = { id = 51693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfangen der Eisenflut" }
quests[51694] = { id = 51694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welche Hexe?" }
quests[51696] = { id = 51696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückfordern, was uns gehört", description = "Ich bin beeindruckt. Ihr habt nicht nur unsere Leute gerettet, sondern auch den Anführer der Angreifer getötet.\n\nOben auf dem Turm ist unser Kriegshorn. Auf sein Signal hin werden unsere Truppen herbeieilen, und wir werden diese Festung wieder unter unsere Kontrolle bringen.\n\n{name}, ich glaube, Ihr habt Euch diese Ehre verdient.", sourceObjective = "Lasst das Kriegshorn erschallen und erlangt die Kontrolle über die Reißzahnfeste im Sturmsangtal zurück.", completion = "Gute Arbeit, {name}.\n\nDie meisten Gebäude waren leicht zu reparieren, aber wir müssen den Kriegshäuptling um weitere Truppen bitten.\n\nWir werden um unseren Platz in diesem Land kämpfen müssen... so viel ist sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[51697] = { id = 51697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach Trüffeljägern" }
