quests[51711] = { id = 51711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombenstimmung", sourceObjective = "Beschafft ein Dynamitbündel und benutzt es, um 16 Minenarbeiter der Reißzahnfeste und 4 Minentechniker zu töten.", progress = "Sie werden keine Chance haben!", completion = "Puh... Bei all diesen Explosionen wird wohl niemand in dieser Mine überlebt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51712] = { id = 51712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Auge", sourceObjective = "Benutzt den Schredderprototyp, brennt 8 Gebäude der Reißzahnfeste nieder und tötet General Schwarzstein sowie 30 Soldaten der Horde.", progress = "Lasst sie für das bezahlen, was sie uns angetan haben.", completion = "Ich kann nicht glauben, dass Ihr das wirklich geschafft habt. Jetzt könnten wir eine echte Chance haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[51714] = { id = 51714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission vom König", description = "Hey, schön, Euch zu sehen! Ein gutes Gefühl zu sehen, wie mein Greif über dem Meer die Schwingen streckt.\n\nIch bin hier, um Euch bei Euren Kriegsanstrengungen zu unterstützen. Ich helfe gerne!\n\nTreffen wir uns mit Meister Shaw, Landratte.\n\nHa! Ich wollte schon immer was Piratisches sagen. Wusstet Ihr, dass man mal ein Schiff nach mir benannt hat? Das war toll!", sourceObjective = "Trefft Euch mit Spionagemeister Mathias Shaw auf der Erlösenden Winde.", completion = "Gut, wir sind alle da. Ich habe ausdrücklich um Eure Anwesenheit gebeten, {name}. Falstad auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[51715] = { id = 51715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg der Schatten", description = "In jedem Krieg wird an verschiedenen Fronten gekämpft, {class}.\n\nKönig Wrynn hat Halford Wyrmbann und seine 7. Legion damit beauftragt, unsere Position in Kul Tiras und in Zandalar zu festigen.\n\nAber ohne uns wird ihnen das nicht gelingen. Wir sind die unsichtbare Hand. Die Schatten in der Dunkelheit.\n\nMich hat man angewiesen, eine Elitetruppe ins Leben zu rufen, und Ihr müsst als Kontaktperson zwischen Wyrmbann und mir dienen.\n\nIhr werdet dabei helfen, unsere Missionen zu planen. Fangen wir an.", sourceObjective = "Schickt Falstad auf eine Mission.", progress = "Ohne uns würde dieser Krieg ohne weiteres verloren sein.", completion = "Ich bin sicher, Falstad wird diese Mission mit seiner üblichen Anmut absolvieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[51717] = { id = 51717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Honig in Vol'dun", description = "Wenn Ihr mit der Rettung der andren allein klarkommt, werd'n Zulsan un' ich zum Gasthaus zurückgeh'n un' erstma' aufräumen.\n\nKeine Sorge, ich brau Euch 'n paar meiner berühmten Skorpidbluttränke zusamm'.\n\nAch ja, Ihr werdet direkt an meinem Freund Rikati vorbeikomm'. Er verkauft den besten Honig in ganz Vol'dun!\n\nBringt mir 'n paar Gläser davon mit, damit die Tränke lecker süß werd'n!", sourceObjective = "Trefft Rikati bei den Vier Stacheln.", completion = "Rhan'ka hat Euch geschickt? Er schuldet mir immer noch was für die letzte Ladung Honig, die ich ihm verkauft habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[51718] = { id = 51718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Honig\" ernten", description = "Ich habe keine Ahnung, was Rhan'ka da unten in der Oase mit dem ganzen Honig macht, den er von mir gekauft hat. Ehrlich gesagt vermute ich, dass ich das gar nicht wissen will.\n\nAber egal, welche Gründe er hat, Rhan'ka ist mein bester Kunde.\n\nObwohl meine Vorräte sich dem Ende zuneigen, werde ich mit Euch eine Sondervereinbarung treffen, weil Rhan'ka Euch geschickt hat.\n\nDie Wespen hier bewahren ihren gesamten Honig in ihren Stacheln auf. Bringt mir ein paar davon, damit ich den Honig herausholen und Euch eine große Ladung von dem klebrigen Zeug für Rhan'ka mitgeben kann.", sourceObjective = "Sammelt 12 Eiterschwingenstachel.", progress = "Keine Panik, wenn etwas Sand hineingerät. Es wird dadurch sicher nicht schlechter schmecken.", completion = "Ich werde nur einen Moment brauchen, um den Honig da rauszuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51719] = { id = 51719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das darf es nicht gleven" }
quests[51720] = { id = 51720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Schreddern", description = "Ich habe schon mal die Lage ausgekundschaftet, während Ihr in der Mine gewütet habt.\n\nIch habe einen riesigen, gepanzerten Schredder in ihrem Sägewerk gesichtet. Ich wette, mit dem Ding könnten wir ganz schön Schaden anrichten!\n\nIch habe versucht, ihn in Gang zu setzen, aber er scheint keinen Saft zu haben. Ob sie vergessen haben, ihn aufzuladen?\n\nSeht, ob Ihr einen frischen Energiekern von einem der anderen Schredder in der Nähe beschaffen könnt.", sourceObjective = "Findet einen energetisierten Kern und installiert ihn im Schredderprototyp MK-03.", progress = "<Energetisierter Kern erforderlich.>", completion = "<Als der Schlüssel einrastet und der neue Kern aktiviert wird, gibt der Schredder ein tiefes Brummen von sich. Das Brummen wird schnell zu einem hohen Sirren, und überall im Cockpit leuchten Instrumentenanzeigen auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[51723] = { id = 51723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sägebespänt", description = "Wenn wir sie davon abhalten wollen, sich in Sturmsang noch weiter auszubreiten, dann müssen wir ihre Holzproduktion lahmlegen!\n\nSie haben nur eine begrenzte Anzahl Holzfäller. Wenn wir einige von denen absägen könnten, wären sie gezwungen, ihre Pläne zu überdenken!", sourceObjective = "Tötet 10 Holzfäller der Reißzahnfeste.", completion = "Gute Arbeit. Das wird ihnen mit Sicherheit einen Dämpfer verpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51726] = { id = 51726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts wie raus hier", description = "Ich kann nicht glauben, dass Ihr hier seid. Bitte, wir brauchen Hilfe!\n\nSie zwingen uns ununterbrochen zur Minenarbeit. Die Schwächsten von uns sterben einer nach dem anderen. Wenn das so weitergeht, sind wir bald alle tot.\n\nDie Ketten sind schwach, vielleicht könnt Ihr das Schloss aufbrechen.\n\nIch halte die Augen offen, bis alle anderen frei sind. Macht Euch um mich keine Sorgen!", sourceObjective = "Befreit 6 gefangene Bergarbeiter.", completion = "Habt Dank für unsere Rettung, wir wären sonst hier drin gefangen gewesen, bis wir alle einer nach dem anderen gestorben wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[51727] = { id = 51727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisen im Visier" }
quests[51728] = { id = 51728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt alles nieder", description = "So, der Flammenwerfer wäre wieder zusammengeflickt! Jetzt werden wir Rache für Brennadam üben!\n\nWenn es brennbar ist, ist es ein Ziel, und wenn nicht, dann muss es wahrscheinlich trotzdem gegrillt werden. Lasst uns diese Belagerungstürme gleich mit niederbrennen, wo wir schon dabei sind.\n\nLegt alles in Schutt und Asche!", sourceObjective = "Brennt 6 Holzstapel und 2 Belagerungstürme nieder.", completion = "Es geht doch nichts über den Geruch von frisch gegrilltem Orc!", sourceObjectiveStatus = "unverified-source-field" }
