quests[51752] = { id = 51752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräulich", description = "Ich habe da einen besonders hässlichen und ziemlich wütenden Goblin gesehen, der den anderen Bergleuten Befehle zugebrüllt hat.\n\nIch möchte wetten, dass er der Kopf des Betriebs ist. Wenn Ihr Euch Zutritt zur Mine verschaffen und ihn eliminieren könnt, wird ihnen das hoffentlich Sand ins Getriebe streuen.", sourceObjective = "Tötet Chefingenieur Grizz.", completion = "Hoffentlich streut sein Tod ihnen Sand ins Getriebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[51753] = { id = 51753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rexxar", sourceObjective = "In zahllosen Kriegen habe ich gelernt, dass diejenigen, die allein kämpfen, fallen werden.\n\nLasst uns wie ein Mann kämpfen, {name}. Gemeinsam stellen wir uns allem entgegen, was unsere Feinde aufbieten können!", sourceObjectiveStatus = "unverified-source-field" }
quests[51754] = { id = 51754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähe Hunde" }
