quests[51769] = { id = 51769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weil ich ein Möwchen bin" }
quests[51770] = { id = 51770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission vom Kriegshäuptling", description = "Lady Sylvanas hat Garona der Halborcin den Befehl erteilt, sich um eine äußerst wichtige Aufgabe zu kümmern.\n\nSie soll Missionen von der Klagelied aus leiten und eine schlagkräftige Truppe zusammenstellen, um unsere Pläne auszuführen.\n\nDas wird für unseren Krieg gegen die Allianz von entscheidender Bedeutung sein, und Eure Unterstützung ist auf jeden Fall erforderlich.", sourceObjective = "Geht mit Garona der Halborcin auf der Klagelied unter Deck.", completion = "Wir dürfen diese Aufgabe nicht auf die leichte Schulter nehmen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51771] = { id = 51771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg der Schatten", description = "Ich habe damit begonnen, Helden für unsere Sache zusammenzurufen. Vielleicht kennt Ihr Arkanistin Valtrois bereits? Wir müssen in Zukunft noch mehr rekrutieren, aber das ist ein vielversprechender Anfang.\n\nUnsere Missionen werden sich um Täuschung, Aufklärung, Attentate und andere fokussierte Schläge gegen unsere Feinde drehen.\n\nStellen wir die Kampfkraft dieser Nachtgeborenen auf die Probe, ja?", sourceObjective = "Schickt Arkanistin Valtrois auf eine Mission.", completion = "Ja, das wird gehen. Die Schatten werden vor Allianzblut blau gefärbt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51772] = { id = 51772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stamm der Tortaka", description = "Habt Ihr schon mal 'nen Tortollaner getroff'n? Die verkauf'n alle möglichen nützlichen Schriftrollen un' Artefakte.\n\nWir ham oft mit dem Stamm der Tortaka gehandelt, aber wir ham seit Wochen nix von denen gehört.\n\nDer Stamm hat 'n Dorf in der Finsterwaldbank. Wir brauchen jemand'n, der mit ihnen Kontakt aufnimmt un' unsre Handelsbeziehungen wieder aufleb'n lässt.", sourceObjective = "Trefft Euch mit Torka.", completion = "Ihr kommt von dem Trollstamm in der Arena? Ich fürchte, wir haben im Moment nicht viel zum Handeln...", sourceObjectiveStatus = "unverified-source-field" }
quests[51773] = { id = 51773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aschenwindbedrohung", description = "Die Handelskompanie Aschenwind betreibt Bergbau im Rotfelshaf'n.\n\nLasst Euch von dem hübsch'n Namen nich' täusch'n, das is' mit Abstand die gefährlichste Piratenbande, der ich je begegnet bin.\n\nVor 'ner Weile hat eins ihrer Mannschaftsmitglieder versucht, mit uns Kontakt aufzunehm'n. Ich brauch jemand'n, der sich mit ihm trifft un' herausfindet, was er will.\n\nEs könnte 'ne Falle sein, aber jede Information, die er über die Handelskompanie Aschenwind hat, könnt für unser Überleb'n wichtig sein.", sourceObjective = "Trefft Euch mit Randall Rotmond.", completion = "{race}, Ihr seht aus wie jemand, der etwas Geld verdienen möchte. Stimmt's oder hab ich recht?", sourceObjectiveStatus = "unverified-source-field" }
quests[51774] = { id = 51774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragna" }
quests[51775] = { id = 51775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Letztwindlager", description = "Eine Vulperakarawane hat vor Kurzem nich' weit von hier ihr Lager aufgeschlag'n.\n\nDas könnt 'ne gute Gelegenheit sein, neue Handelsbeziehungen mit dem Stamm einzugeh'n.\n\nDie Wüste is'n gefährlicher Ort, {name}. Geht un' seht nach, ob sie Hilfe brauch'n. Ich bin sicher, sie können erfahr'ne Hände wie Eure brauch'n.\n\nAls Gegenleistung sin' sie vielleicht bereit, dem Stamm Rabatt auf Waren un' Dienstleistungen anzubiet'n.", sourceObjective = "Sprecht mit Norah.", completion = "Ihr seid also von den Trollen in der Arena geschickt worden und sucht nach Arbeit? Ich mache gern Geschäfte mit Euch, wenn Ihr mir ein bisschen helft...", sourceObjectiveStatus = "unverified-source-field" }
quests[51776] = { id = 51776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orkansturm" }
