quests[51781] = { id = 51781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorarbeiter Zettel" }
quests[51782] = { id = 51782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Klingenstachel" }
quests[51783] = { id = 51783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung von Zem'lan" }
quests[51784] = { id = 51784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spaziergang auf einem Friedhof", description = "Unser nächster Halt ist Drustvar.\n\nDort werden wir mit etwas Hilfe die Leiche eines Kriegshelden aus Kul Tiras identifizieren und bergen.\n\nMit seiner Hilfe werden wir viel über die Flotte aus Kul Tiras lernen. Genug, um sie mit Leichtigkeit zu vernichten.\n\nWir treffen uns vor dem Grabhügelfriedhof.\n\nEs wäre nett, wenn Ihr keine Zeit verschwenden würdet.", sourceObjective = "Trefft Nathanos Pestrufer vor dem Grabhügelfriedhof.\n\nSchreckensadmiralin Segelriss kann Euch nach Drustvar bringen.", completion = "Ah, {name}. Da seid Ihr ja.\n\nIhr erinnert Euch an Kapitänin Stein, nicht wahr? Ich glaube, Ihr werdet merken, dass sie jetzt etwas... zugänglicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[51785] = { id = 51785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabinschriften untersuchen", description = "Ohne Steins Kenntnisse wird bei der Mission etwas zusätzliche Laufarbeit nötig sein.\n\nLest die Plaketten auf dem Friedhof. Findet die wichtigste Leiche.\n\nDer Rest sollte ziemlich einfach sein.", sourceObjective = "Untersucht 4 Grabplaketten auf dem Grabhügelfriedhof.", completion = "Marschall M. Valentin... Ja, der Name kommt mir bekannt vor. In einer verschlossenen Gruft, sagt Ihr?\n\nNun, das kann man umgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51786] = { id = 51786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Zustand der Unruhe", description = "Eins solltet Ihr über Geister wissen, {name}.\n\nSie sind eine Verhöhnung der Toten. Geister klammern sich an etwas fest, obgleich sie keine Hoffnung haben. In dieser Form werden sie niemals wieder richtig leben. Nicht, solange sie in unserer Welt herumspuken.\n\nAber wenn sie zu ihren Körpern zurückkehren, dann können sie uns eines Tages vielleicht von Nutzen sein.\n\nErlöst diese Geister von ihrem Elend.", sourceObjective = "Tötet 8 wütende Geister.", completion = "Vielleicht werden wir eines Tages für diese Leute Verwendung haben.\n\nSie werden sicherlich dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[51787] = { id = 51787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Los im Leben", description = "Amalia bekommt das Leben als Untote scheinbar nicht.\n\nIch kenne ein Kraut, das vielleicht hilft.\n\nDieser Friedhof ist mit Grabblüten übersät. Den Lebenden verleihen sie die Gabe, die Geister zu sehen.\n\nWas die Untoten angeht...\n\nEs wird sie vielleicht gerade genug an die Realität binden, um... bei Verstand zu bleiben.", sourceObjective = "Sammelt 10 Grabblüten.", progress = "Ich weiß, was Amalia gerade durchmacht... Sie wird lernen, ihren neuen Status als Verlassene zu akzeptieren.\n\nIch werde ihr dabei helfen.", completion = "Ah, ja... in einwandfreiem Zustand.\n\nDas sollte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[51788] = { id = 51788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gruftwächter", description = "Ich habe den Friedhof immer im Blick behalten.\n\nEs gibt dort einen Geist, der im Gegensatz zu den anderen nicht ziellos umherwandert.\n\nEr ist der Gruftwächter, der Hüter der Schlüssel.\n\nWenn wir an Valentins Leiche herankommen wollen, dann werden wir erst an dem Geist vorbeimüssen.", sourceObjective = "Sammelt Valentins Schlüssel von Brutus Dörner ein.", progress = "Nichts kann uns aufhalten. Nicht heute.", completion = "Bleibt nur noch eine Sache zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[51789] = { id = 51789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was von Marschall M. Valentin übrig blieb", description = "Wir haben den Schlüssel und auch die Gruft gefunden.\n\nAls Nächstes wird Valentins Leichnam uns gehören.\n\nWir müssen nicht auf Lilian und Stein warten. Beenden wir das jetzt.", sourceObjective = "Helft Nathanos Pestrufer dabei, Valentins Leichnam zu bergen.", progress = "Wir haben keine Zeit zu vertrödeln. Wir haben Pläne umzusetzen.", completion = "Noch eine Unannehmlichkeit. Immerhin hat Stein sich endlich als nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51791] = { id = 51791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasentotemtest" }
quests[51792] = { id = 51792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eruptionstotemtest" }
quests[51793] = { id = 51793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasentotemtest" }
quests[51794] = { id = 51794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eruptionstotemtest" }
quests[51795] = { id = 51795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Lordaeron", description = "König Wrynn hat unsere Streitkräfte zusammengerufen, {name}. Wir planen einen Großangriff auf Lordaeron.\n\nWir werden die Horde aus der Burg vertreiben und sie für die Allianz erobern. Es ist schon viel zu lange her, dass unsere Fahne über Tirisfal geweht hat.\n\nBereit zum Auslaufen? Kapitänin Angelika wird für Euren Transport sorgen.", sourceObjective = "Beendet die Schlacht um Lordaeron.", completion = "Gut, dass Ihr wieder auf den Beinen seid, {name}. Viele andere hatten nicht so viel Glück.\n\n\n\nKönig Anduin ist nach Burg Sturmwind zurückgekehrt. Er muss entscheiden, was unser nächster Schritt sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[51796] = { id = 51796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Lordaeron", description = "Die Allianz hat ihre Truppen zusammengezogen und marschiert auf Unterstadt.\n\nDer Krieg hat nun wirklich begonnen.\n\nUnsere Magierin wird Euch einweisen. Geht.\n\nÜberprüft unsere Verteidigung und bringt die Zivilisten in Sicherheit. Ich schließe mich Euch bald an.\n\nLok-tar ogar, {name}.", sourceObjective = "Beendet die Schlacht um Lordaeron.", completion = "Unser Krieg hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51797] = { id = 51797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeitenweisen aufspüren", description = "Rexxar hat einen mächtigen Gezeitenweisen verfolgt, der uns helfen soll, den Leichnam von Marschall Valentin zu finden. Er hat gemeldet, dass es einen Durchbruch gab.\n\nReist nach Sturmsang, helft dem Halboger und Lilian, diesen Gezeitenweisen zu finden und ihn dem Willen der Horde zu unterwerfen.\n\nKommt nicht ohne einen Weg zurück, Marschall Valentin zu finden.", sourceObjective = "Trefft Rexxar in der Reißzahnfeste im Sturmsangtal.", completion = "{name}. Ich weiß, was die Horde braucht. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51798] = { id = 51798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Preis ist zu hoch", description = "Ich habe einen Gezeitenweisen bis zu einem Lager in der Nähe verfolgt. Er weilt dort mit seiner Familie.\n\nDoch seid gewarnt: Gezeitenweise sind mächtige Gegner. Sie beherrschen alle Elemente, und manche von ihnen gebieten sogar über die Leere.\n\nWenn dieser Mann bei seiner Familie ist, gibt er sich möglicherweise nicht so leicht geschlagen. \n\nHoffen wir nur, dass er vernünftig genug ist, sie da nicht hineinzuziehen.\n\nKommt.", sourceObjective = "Helft Rexxar dabei, einen Gezeitenweisen aufzuspüren.", completion = "Hoffen wir, dass dieser Gezeitenweise die Wahrheit sagt, sonst wird die Sache noch sehr blutig.", sourceObjectiveStatus = "unverified-source-field" }
quests[51800] = { id = 51800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Tiragardesund", description = "An der Küste vom Tiragardesund gibt's 'ne Menge Pirat'n.\n\nIch hab den Ersten Maat von 'ner Mannschaft kontaktiert. Die Dame denkt, wir könn' uns den Kapitän vorknöpf'n und dabei 'nen schönen Außenposten abstaub'n.\n\n          - Schattenjäger Ty'jin", sourceObjective = "Helft Schattenjäger Ty'jin im Tiragardesund.", sourceObjectiveStatus = "unverified-source-field" }
quests[51801] = { id = 51801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Drustvar", description = "In Drustvar gibt es offenbar ein großes unterirdisches Azeritflöz.\n\nMacht Ihr gerne Gewinne? Mir sind sie das ALLERLIEBSTE. Das scheint mir eine goldene Chance zu sein, wenn Ihr versteht, was ich meine. Zeit ist Geld!\n\n          - Handelsprinz Gallywix", sourceObjective = "Helft Gallywix und Etrigg in Drustvar.", sourceObjectiveStatus = "unverified-source-field" }
quests[51802] = { id = 51802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stützpunkt: Sturmsangtal", description = "Wir haben in der sogenannten Reißzahnfeste im Sturmsangtal einen Außenposten errichtet und verstärkt.\n\nAber wir sind von Truppen aus Kul Tiras umzingelt. Ein Angriff steht unmittelbar bevor, und wir benötigen Verstärkung. Verschwendet keine Zeit.\n\n                                 - Rexxar", sourceObjective = "Helft Rexxar im Sturmsangtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[51803] = { id = 51803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kampagne in Kul Tiras", description = "Unser Feind verbreitet seinen Einfluss in ganz Kul Tiras und rekrutiert neue Verbündete im Kampf gegen die Horde.\n\nWir müssen im Feindesland Fuß fassen, wenn wir diesen Krieg gewinnen wollen.\n\nDer Kriegshäuptling benötigt Eure Unterstützung, um Außenposten im Sturmsangtal, in Drustvar und im Tiragardesund abzusichern.\n\nWelchen Ort sollen wir uns zuerst vornehmen?", sourceObjective = "Verwendet die Kampagnenkarte von Kul Tiras, um einen Stützpunkt auszuwählen.", completion = "Ihr genießt das Vertrauen der Königin. Vorerst.", sourceObjectiveStatus = "unverified-source-field" }
quests[51804] = { id = 51804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgesetzte Einmischung" }
quests[51805] = { id = 51805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden das Fürchten lernen", description = "Endlich bietet sich uns eine Gelegenheit, der Allianz UND Kul Tiras einen Schlag zu verpassen!\n\nAm Weisenwall wimmelt es von Initianden der Gezeitenweisen, die Magie studieren und Kul Tiranern, die versuchen, den Ort gegen einen Angriff der Horde zu befestigen.\n\nZeigen wir ihnen, was wahre Furcht bedeutet, damit sie es sich noch einmal überlegen, ob es wirklich so klug ist, der Allianz im Kampf gegen die Horde zu helfen.\n\nNehmt dieses Horn. In meinen Händen beschwört es eine Val'kyr, in den Euren hingegen wird es unsere Feinde mit Angst und Schrecken erfüllen.\n\nDas ist ein großes Zeichen meines Vertrauens. Enttäuscht mich nicht.", sourceObjective = "Terrorisiert 20 Bauarbeiter von Kul Tiras oder Gezeitenweisenrekruten mit dem Val'kyrhorn.", completion = "Ich konnte ihre Schreie bis hier hören! Vielleicht werden die Kul Tiraner ihre Unterstützung für die Allianz noch einmal überdenken!", sourceObjectiveStatus = "unverified-source-field" }
quests[51806] = { id = 51806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfer MK. II" }
quests[51810] = { id = 51810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Hartford", description = "Ich bin fast so weit, Vol'dun ein für alle Male zu verlassen. Es gibt nur noch eins zu erledigen...\n\nWir müssen den Kapitän dieses Schiffs umbringen.\n\nWenn Kapitän Hartford herausfindet, dass ich desertiert bin, werde ich weder in Boralus noch sonst wo sicher sein. Er wird mich bis in die Östlichen Königreiche und zurück jagen, wenn es sein muss!\n\nDas hier wird gefährlich. Ihr solltet Euch also verkleiden, bevor Ihr an Bord der Sirenenlied geht.\n\nDiese wird unsere letzte gemeinsame Aufgabe sein. Erledigt sie und ich werde Euch den Code für die Schließkassette des Käpt'ns verraten. Ein Piratenschatz!", sourceObjective = "Tötet Kapitän Hartford.", completion = "Ein Hoch auf den früheren Kapitän der Sirenenlied. Er war ein guter Mann, aber gute Männer leben hier nicht lange!", sourceObjectiveStatus = "unverified-source-field" }
quests[51811] = { id = 51811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene Tortollaner" }
quests[51813] = { id = 51813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzfelstiefen", description = "Habt Ihr davon gehört, wie die Dunkeleisenzwerge der Allianz beigetreten sind? Eine höchst unerwartete Wendung der Ereignisse.\n\nTapfere Helden der Allianz bekämpften jahrelang die Dunkeleisenzwerge, bis sich ihre Ränge spalteten.\n\nMoira Thaurissan, die entfremdete Tochter des früheren Zwergenkönigs Magni Bronzebart, führte eine Fraktion der Dunkeleisenzwerge an.\n\nMoira wollte die Allianz unterstützen und bot an, in den Schwarzfelstiefen bei der Erforschung von Azerit und seinem potenziellen Nutzen zu helfen.", sourceObjective = "Sprecht mit Moira an der Botschaft von Sturmwind, um in die Schwarzfelstiefen zu reisen.", progress = "Die Gedankengänge eines Zwergs sind etwas Herrliches.", completion = "Herumpfuschende Goblinbastarde!\n\n<Moira atmet tief durch.>\n\nTut mir leid, ich kann diese grünen Widerlinge einfach nicht ertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51814] = { id = 51814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravierende Bedrohung" }
quests[51815] = { id = 51815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierausrottung" }
quests[51816] = { id = 51816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutatenpterror" }
quests[51817] = { id = 51817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene Tortollaner" }
quests[51818] = { id = 51818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant und Kapitänin", description = "Das macht mir keine Freude, {name}, aber ich werde für das Glück und die Sicherheit meiner Familie alles tun, was getan werden muss.\n\nMir wäre es lieber, wir könnten auf Gewalt verzichten, aber wenn es nicht anders geht... Es gibt zwei Ziele, ihre Anführer. Kapitänin Malia und Kommandant Augustin.\n\nIhr Verlust sollte die beiden Gruppen zum Rückzug aus dem Gebiet zwingen. \n\nAugustin hat außerdem ein Buch konfisziert, das mir gehört. Bringt es mir wieder, und meine Kräfte gehören Euch... für die Zeit, die mir noch vergönnt ist.", sourceObjective = "Tötet Kapitänin Malia und besorgt das Buch der verbotenen Magie von Kommandant Augustin.", progress = "Ich muss nicht bis ins kleinste Detail wissen, was dort unten passiert ist. Ich brauche einfach nur das Buch.", completion = "Ich werde mich nicht mit den grausamen Dingen aufhalten, die Ihr tun musstet... Aber ich werde Euch zeigen, wozu dieser sterbende Mann im Besitz seines Buches noch imstande ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[51819] = { id = 51819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstreuung unserer Feinde", description = "Wir kundschaften das Gebiet um Weisenwall nun schon seit einiger Zeit aus. Der Wall wurde kürzlich von einer großen Streitkraft der Allianz und der Kul Tiraner zurückerobert.\n\nWir warten seither auf eine Gelegenheit zurückzuschlagen, wenn ihre Verteidigung geschwächt ist. Und diese Gelegenheit hat sich nun eröffnet.\n\nGeht hinunter nach Weisenwall und zeigt den verbleibenden Truppen, was jenen widerfährt, die sich gegen die Horde auflehnen.", sourceObjective = "Tötet 10 Soldaten der Allianz und aus Kul Tiras in Weisenwall.", completion = "Gut. Wenn wir hier fertig sind, sollte die Gegend um Weisenwall wieder von den rebellischen Gezeitenweisen bevölkert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[51820] = { id = 51820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ölige Sauerei" }
quests[51821] = { id = 51821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung in der Bucht" }
quests[51822] = { id = 51822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schriftrollen und Schuppen" }
quests[51824] = { id = 51824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenständig" }
quests[51827] = { id = 51827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie kamen von hinten!" }
quests[51828] = { id = 51828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legion niederbrennen" }
quests[51829] = { id = 51829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranahs Schraubenschlüssel", description = "<Der Schraubenschlüssel ist durch ständigen Gebrauch abgenutzt, scheint aber sonst in gutem Zustand zu sein.\n\nAuf dem Griff ist ein Name eingraviert: Ranah.>", sourceObjective = "Bringt den Schraubenschlüssel zu Ranah in der Verdorrenden Schlucht.", progress = "Habt Ihr etwas für mich?", completion = "Danach habe ich überall gesucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[51830] = { id = 51830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zellings Potenzial", description = "<Hust> Mein Körper wird nicht viel länger durchhalten, aber Fräulein Voss besteht darauf, dass ich meine wahre Macht demonstriere.\n\nIch kann Euch mit einem <hust> <keuch> magischen Quell ausstatten, der für Euch die Leerenessenz getöteter Kreaturen aufnimmt.\n\nWenn der Quell gefüllt ist, könnt Ihr einen verheerenden magischen Windschlag entfesseln.\n\nGeht zum <hust> Nebelfluthafen. Dort werdet Ihr jene finden, die von der Leere verderbt wurden.\n\nTötet sie, füllt den Quell und Ihr werdet <keuch> meine Magie in Aktion erleben.", sourceObjective = "Füllt Zellings Leerenquell, indem Ihr im Nebelfluthafen Feinde tötet. Entfesselt dann Zellings verheerende Windmagie.", progress = "Und? <hust> Reicht Euch das?", completion = "Wir alle haben <hust> die Magie von hier aus gesehen. Fräulein Voss glaubt, dass die Zeit gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[51831] = { id = 51831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Offensive" }
