quests[51836] = { id = 51836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcen beschaffen" }
quests[51837] = { id = 51837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sein wird, wird sein", description = "So, da sind wir. Zelling könnte für uns von großem Vorteil sein, solange wir sicherstellen, dass seine Familie versorgt ist.\n\nEr hat nicht mehr viel Zeit. Mal sehen, ob er Marschall Valentin für uns finden kann, bevor er stirbt.", sourceObjective = "Bringt Zelling dazu, Marschall Valentin aufzuspüren.", completion = "Wir sollten lieber aufbrechen. So gerne ich es ja hätte, dass sich das hier anders entwickelt... es sieht nicht danach aus.", sourceObjectiveStatus = "unverified-source-field" }
