quests[51856] = { id = 51856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tiefenpfuhl: Moderschlund" }
quests[51870] = { id = 51870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inselexpedition", description = "Unsere Spione haben eine Nachricht der Allianz abgefangen, in der eine Azeritablagerung im Großen Meer beschrieben wird.\n\nDie Klagelied ist nicht schnell genug, um uns vor ihnen dorthin zu bringen. Glücklicherweise habe ich dafür gesorgt, dass ein Schiff der Zandalari aufgetakelt wird und für Gelegenheiten wie diese bereit steht.\n\nSprecht mit Käpt'n Rez'okun auf der Westseite der Docks. Er weiß Bescheid und sollte Euch bereits erwarten.", sourceObjective = "Meldet Euch bei Käpt'n Rez'okun im Hafen von Zandalar.", completion = "Seid Ihr der Hordechampion, auf den ich warte? Dann ma an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[51874] = { id = 51874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollgefressener Eber" }
quests[51881] = { id = 51881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Minenräumer", description = "<Einer der Goblinflammenwerfer. Er hat jedoch leider Risse im Tank. Es wäre eine gute Idee, ihn zu Frederike zurückzubringen. Sie hat vielleicht etwas, um ihn zu reparieren.>", sourceObjective = "Liefert den gesprungenen Minenräumer bei Frederike Götzstein vor der Salzsteinmine ab.", completion = "Ein Flammenwerfer!? Der könnte ziemlich nützlich sein, aber wieso konntet Ihr keinen in besserem Zustand finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[51884] = { id = 51884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchgebrannter Golem" }
quests[51886] = { id = 51886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nad el Kissen" }
quests[51887] = { id = 51887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungustrio" }
quests[51888] = { id = 51888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inselexpedition", description = "Wir sollt'n uns lieber beeil'n, wenn wir vor der Allianz auf der Insel sein woll'n.\n\nFertig?", sourceObjective = "Sprecht mit Käpt'n Rez'okun, um die Expedition zu beginnen, und erforscht dann die Unerforschte Insel.", completion = "Gute Arbeit, {name}. Wir sind 'n gutes Team. Lasst uns das bald wiederhol'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51889] = { id = 51889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache der Weintrauben", description = "Ihr kommt mir bekannt vor. Schuldet Ihr mir Geld? Moment... nein, das ist es nicht.\n\nWenn Ihr hier seid, weil Ihr was lernen wollt, kann ich Euch meine geheime Bergbaumethode zeigen, aber... uff...\n\nIm Moment bin ich hauptsächlich damit beschäftigt, den Kopf klar zu kriegen. Ächz... Ich fühl mich, als würde mir jemand den Schädel mit 'ner Spitzhacke einschlagen. \n\nDas beste Mittel gegen so einen Kater ist Einmachessig, ein großes deftiges Frühstück und was immer ich auch gestern Abend nicht ausgetrunken habe.\n\nWie wär's denn damit? Ihr bringt mir so schnell und leise wie möglich so ein Frühstück, und ich bring Euch bei, was immer Ihr wissen wollt.", sourceObjective = "Bringt Franko dem Säufer ein Glas Einmachessig, einen Berg Speck, einen Stapel Würste und einen Haufen Eier.", progress = "Diese Schatten sind so laut. Könnt Ihr da nicht auch was gegen machen?", completion = "Das hab ich gebraucht!\n\n<Franko schaufelt sich das Essen in den Mund.>\n\nMmm... Also gut! Wenn ich mich recht entsinne, habt Ihr nach Sturmsilberflözen gefragt?\n\nDann werde ich Euch jetzt meine Geheimtechnik verraten, die nicht einmal Mirte kennt. Das Metall neigt bei äußerer Krafteinwirkung zu Brüchen. Anstatt das Metall an der Nahtstelle zum Felsen abzutrennen, ist es daher besser, gleich den ganzen Stein zu entfernen.\n\nDas Metall bildet natürliche Prismen und lässt sich ganz leicht aus dem Stein ziehen, wenn alles erst mal gelockert ist. So geht nichts davon verloren.", sourceObjectiveStatus = "unverified-source-field" }
